sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    //Type appropriate comment here, and begin script below
	// Created By : Shivam Dighe
	// Created on : 21/07/2026
	// Purpose : To make the model field visible when asset type is hardware and to make business justification field mandatory when asset type is software

    var assetType = g_form.getValue('asset_type');
    if (assetType == 'software') {
        g_form.setDisplay('model', false);
        g_form.setMandatory('business_justification', true);
    } else {
        g_form.setDisplay('model', true);
        g_form.setMandatory('business_justification', false);
    }

}
